// Core Testing Fundamentals — Part 3 (q211–315)
window.QUIZ_BANK['core-testing'] = (window.QUIZ_BANK['core-testing']||[]).concat([
{id:211,topic:'core-testing',difficulty:'beginner',question:'Which of the following is the BEST description of a "test plan"?',options:['A list of all test cases','A document describing the scope, objectives, approach, resources, schedule, and risks of testing activities','A report produced after test execution','A set of automated test scripts'],answer:1,explanation:'A test plan documents the testing strategy, scope, objectives, resources, schedule, and risk mitigation approach for a testing engagement.'},
{id:212,topic:'core-testing',difficulty:'beginner',question:'What does "test execution" primarily involve?',options:['Designing test cases from requirements','Running test cases against the SUT and recording actual results','Writing the test plan','Submitting defects to the development team'],answer:1,explanation:'Test execution is the act of running test cases against the system under test, comparing actual outputs to expected results, and logging pass/fail/blocked outcomes.'},
{id:213,topic:'core-testing',difficulty:'beginner',question:'Which of the following is NOT a valid defect status?',options:['Open','Rejected','Retest','Executed'],answer:3,explanation:'"Executed" is a test case status (run/not run), not a defect lifecycle status. Valid defect statuses include New, Open, Assigned, Fixed, Retest, Closed, Rejected, Deferred.'},
{id:214,topic:'core-testing',difficulty:'beginner',question:'What is a "test objective"?',options:['The tool used to track test execution','A reason or goal for designing and running tests — e.g., to verify requirements coverage or assess quality','The deadline for completing testing','The person responsible for signing off on testing'],answer:1,explanation:'Test objectives define what testing should achieve: finding defects, verifying requirements coverage, building confidence, providing risk information, or meeting regulatory obligations.'},
{id:215,topic:'core-testing',difficulty:'beginner',question:'Which of the following is a characteristic of a good tester?',options:['Avoids communication with developers to maintain independence','Has an inquisitive mindset, attention to detail, good communication skills, and analytical thinking','Only focuses on automated testing','Rarely questions requirements'],answer:1,explanation:'Effective testers combine technical skills with critical thinking, curiosity, systematic analysis, good communication, and the ability to question assumptions constructively.'},
{id:216,topic:'core-testing',difficulty:'beginner',question:'What does the ISTQB Foundation Level certification assess?',options:['Advanced knowledge of test automation frameworks','Core software testing concepts, terminology, and best practices at an introductory level','Project management skills for QA leads','Specialised performance testing skills'],answer:1,explanation:'ISTQB CTFL assesses fundamental testing knowledge: principles, lifecycle, design techniques, management, tools, and defect management at a foundational level.'},
{id:217,topic:'core-testing',difficulty:'beginner',question:'Which of the following best describes "specification-based testing"?',options:['Deriving tests from the internal code structure','Deriving tests from documented requirements, specifications, or models without knowledge of the internal implementation','Only testing application performance','Running tests without any defined expected results'],answer:1,explanation:'Specification-based (black-box) testing derives test cases from the functional specification or requirements, focusing on observable inputs and outputs without internal knowledge.'},
{id:218,topic:'core-testing',difficulty:'beginner',question:'What is the main purpose of a "test summary report"?',options:['To list all planned test cases','To provide stakeholders with an assessment of test results, quality status, and remaining risks at the end of a test phase','To assign defects to developers','To define the testing schedule'],answer:1,explanation:'The test summary report communicates the testing outcome: execution results, pass/fail rates, defect metrics, residual risks, and a quality assessment to stakeholders.'},
{id:219,topic:'core-testing',difficulty:'beginner',question:'Which testing type is performed during the development phase by developers to verify individual modules work correctly?',options:['Acceptance testing','System testing','Unit testing','Integration testing'],answer:2,explanation:'Unit testing is performed by developers to verify individual code units (functions, methods, classes) in isolation before integration.'},
{id:220,topic:'core-testing',difficulty:'beginner',question:'What is a "mock object" in unit testing?',options:['A real database used for testing','A simplified object that simulates the behaviour of a real dependency, allowing the unit under test to be tested in isolation','A test environment that mirrors production','The expected output of a unit test'],answer:1,explanation:'Mock objects are test doubles that replace real dependencies (databases, external services) with controlled, verifiable substitutes to isolate the unit being tested.'},
{id:221,topic:'core-testing',difficulty:'intermediate',question:'In a state transition diagram, what does a "transition" represent?',options:['A state the system can be in','The movement from one state to another triggered by an event or condition','The action performed when entering a state','The initial state of the system'],answer:1,explanation:'A transition is the path from one state to another triggered by a specified event or guard condition, optionally associated with an action.'},
{id:222,topic:'core-testing',difficulty:'intermediate',question:'Which test design technique is best for testing a system that processes tax brackets with several distinct rate ranges?',options:['State transition testing','Boundary value analysis and equivalence partitioning','Use case testing','Path coverage testing'],answer:1,explanation:'Tax bracket systems have clearly defined ranges with distinct processing — EP identifies the partitions (each bracket) and BVA targets the boundary values between them.'},
{id:223,topic:'core-testing',difficulty:'intermediate',question:'What is "test automation ROI" typically measured by?',options:['Number of automated tests written per sprint','Reduced total cost of test execution over time minus the cost of building and maintaining automation','Speed of the CI pipeline in minutes','Percentage of regression suite automated'],answer:1,explanation:'Automation ROI = (savings from reduced manual execution) − (cost to build + maintain automation). It considers execution frequency, defect detection value, and maintenance overhead.'},
{id:224,topic:'core-testing',difficulty:'intermediate',question:'A tester has limited time and cannot execute all test cases. Which approach BEST helps them decide what to test?',options:['Execute test cases in the order they were written','Prioritise by risk: test high-risk, high-impact areas first','Execute the most recently written test cases','Ask the developer which tests to skip'],answer:1,explanation:'Risk-based prioritisation ensures the most critical functionality and highest-risk areas are tested first, maximising defect detection within time constraints.'},
{id:225,topic:'core-testing',difficulty:'intermediate',question:'What does "test reporting" provide that raw test results do not?',options:['Individual pass/fail status per test case','Summarised, interpreted quality information: trends, metrics, risk assessment, and recommendations for stakeholders','A list of all open defects','The full execution log with timestamps'],answer:1,explanation:'Test reports transform raw execution data into meaningful stakeholder information: quality trends, risk exposure, coverage gaps, and go/no-go recommendations.'},
{id:226,topic:'core-testing',difficulty:'intermediate',question:'In agile testing, which activity corresponds to system testing but within the sprint context?',options:['Unit testing','Exploratory testing of newly developed stories','Sprint planning','Daily stand-up'],answer:1,explanation:'Within a sprint, testers perform exploratory and acceptance testing of newly developed stories, which is functionally equivalent to system-level validation within the agile context.'},
{id:227,topic:'core-testing',difficulty:'intermediate',question:'What is "test debt"?',options:['Outstanding invoices for testing tools','Accumulated shortcuts in testing (skipped tests, insufficient automation, poor test data) that create future quality risk','The backlog of unresolved defects','Outstanding tasks in the test plan'],answer:1,explanation:'Test debt mirrors technical debt: when teams cut corners in testing (skipping tests, low coverage) to meet deadlines, they accumulate a quality risk that must eventually be addressed.'},
{id:228,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is an advantage of "test-first" approaches like TDD and BDD?',options:['Tests are written after all code is complete, ensuring accuracy','Developers gain immediate feedback and requirements clarification before writing implementation code','Tests are optional and only written when time permits','Code coverage is automatically 100%'],answer:1,explanation:'Test-first approaches (TDD/BDD) force requirement clarification before coding, provide instant feedback during development, and produce inherently testable code.'},
{id:229,topic:'core-testing',difficulty:'intermediate',question:'What is "branch coverage" (also called decision coverage)?',options:['Testing each individual statement once','Ensuring every branch (true and false) of every decision point in the code is executed at least once','Executing every possible path through the code','Testing each condition independently'],answer:1,explanation:'Branch coverage requires every conditional branch (both the true and false outcomes of every if/switch/loop decision) to be exercised, providing stronger coverage than statement coverage alone.'},
{id:230,topic:'core-testing',difficulty:'intermediate',question:'What does "defect triage" involve?',options:['Automatically assigning defects to developers based on module ownership','A structured review meeting where defects are evaluated for severity, priority, and assignment by key stakeholders','Closing all low-priority defects before release','Automating defect detection using static analysis'],answer:1,explanation:'Defect triage is a regular meeting where the team (QA, dev, PM) reviews newly logged defects to agree on severity, priority, assignment, and whether to fix or defer them.'},
{id:231,topic:'core-testing',difficulty:'intermediate',question:'What is the primary goal of "acceptance testing" in an agile project?',options:['Finding as many bugs as possible','Confirming that the user story meets the agreed acceptance criteria and the product owner accepts it','Verifying code quality metrics','Running the automated regression suite'],answer:1,explanation:'In agile, acceptance testing verifies that each user story satisfies its acceptance criteria and that the product owner (customer representative) is satisfied.'},
{id:232,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is a quality attribute that "security testing" primarily measures?',options:['Performance efficiency','Functional suitability','Security','Maintainability'],answer:2,explanation:'Security testing evaluates the security quality attribute: confidentiality, integrity, availability, non-repudiation, authentication, and authorisation of the system.'},
{id:233,topic:'core-testing',difficulty:'intermediate',question:'What is "condition coverage" in white-box testing?',options:['Executing every branch in the code','Ensuring every individual condition within a composite decision evaluates to both true and false at least once','Running every executable statement','Testing all paths through the code'],answer:1,explanation:'Condition coverage requires each individual boolean sub-expression within compound conditions (e.g., A && B) to be evaluated as both true and false, independently of the overall decision outcome.'},
{id:234,topic:'core-testing',difficulty:'intermediate',question:'Why is "test independence" important in static testing reviews?',options:['Testers can review their own work more efficiently','Independent reviewers are not subject to confirmation bias and find defects that authors miss due to familiarity with the material','Developers cannot participate in reviews','Reviews must always be automated'],answer:1,explanation:'Independent reviewers approach work products without the author\'s assumptions and blind spots; they detect ambiguities, errors, and omissions the author overlooked due to familiarity bias.'},
{id:235,topic:'core-testing',difficulty:'intermediate',question:'What is the "V-model" in software testing?',options:['A visual diagram of velocity in agile sprints','An SDLC model that pairs each development phase with a corresponding testing phase, emphasising testing planning parallel to development','A tool for visualising test coverage','A version control workflow'],answer:1,explanation:'The V-model maps each development artefact (requirements, architecture, design, code) to a corresponding verification/validation test level (AT, SIT, ST, UT), with testing planned in parallel with development.'},
{id:236,topic:'core-testing',difficulty:'intermediate',question:'What is "test-driven data management"?',options:['Managing test cases in a database','Creating test data based on the needs identified during test design, rather than adapting tests to pre-existing data','Driving data architecture decisions from test requirements','Using spreadsheets to manage test execution'],answer:1,explanation:'Test-driven data management starts from test design requirements: what data is needed for each test condition, then provisions exactly that data — avoiding the common trap of limited, unsuitable pre-existing data.'},
{id:237,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is the MOST important quality of automated regression tests?',options:['They should test as many features as possible in one test','They should be stable, deterministic, maintainable, and run quickly','They should always be written by QA, never developers','They should be run only on weekends to avoid disrupting development'],answer:1,explanation:'Automated regression tests must be reliable (deterministic), fast (provide quick feedback), maintainable (low cost to update), and independently verifiable to deliver lasting CI/CD value.'},
{id:238,topic:'core-testing',difficulty:'intermediate',question:'What is "time boxing" in exploratory testing?',options:['Setting a maximum time limit (e.g., 90 minutes) for an exploratory testing session to maintain focus and produce measurable outputs','Testing timers and clock features','Scheduling regression runs at fixed daily intervals','Tracking the time each developer spends fixing defects'],answer:0,explanation:'Time-boxing exploratory sessions (typically 60–120 minutes) improves focus, enables better metrics collection, and makes session reporting more consistent.'},
{id:239,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is a weakness of white-box testing alone?',options:['It cannot achieve 100% branch coverage','It does not verify that all specified requirements are implemented; it only tests what was coded','It requires more tools than black-box testing','It always takes longer than black-box testing'],answer:1,explanation:'White-box testing verifies the code as written but cannot detect missing functionality — if a feature was never coded, white-box tests will not expose its absence.'},
{id:240,topic:'core-testing',difficulty:'intermediate',question:'What is "equivalence class" in testing?',options:['A set of test cases that are equivalent in difficulty','A group of input values that are expected to be processed identically by the system, so only one representative value needs to be tested','A class of defects with similar root causes','A group of equivalent automated test frameworks'],answer:1,explanation:'An equivalence class (partition) groups values that should trigger the same behaviour; testing one representative from each class is as effective as testing all values within it.'},
{id:241,topic:'core-testing',difficulty:'advanced',question:'What does "contract testing" prevent in a microservices architecture?',options:['API versioning conflicts','Breaking changes to service interfaces that cause consumer integration failures when services are deployed independently','Database schema migrations','Security vulnerabilities in API endpoints'],answer:1,explanation:'Contract testing (e.g., with Pact) ensures that when a provider service changes its API, consumer expectations are verified, preventing deployed services from silently breaking each other.'},
{id:242,topic:'core-testing',difficulty:'advanced',question:'In test automation, what is the "Page Object Model" (POM) and why is it used?',options:['A database model for storing test results','A design pattern that encapsulates page structure and interactions into classes, separating test logic from UI element locators to improve maintainability','A tool for rendering mobile pages in tests','A model for managing browser instances in parallel'],answer:1,explanation:'POM centralises page element locators and interaction methods; when the UI changes, only the page object needs updating — not every test that uses that page.'},
{id:243,topic:'core-testing',difficulty:'advanced',question:'What is "risk coverage" in test planning?',options:['The percentage of lines of code with tests','The extent to which identified product risks have been addressed by test cases and mitigation strategies','The number of risks found during testing','The ratio of blocked tests to total planned tests'],answer:1,explanation:'Risk coverage maps each identified product risk to the tests that address it, ensuring the test plan provides measurable risk mitigation across all identified hazard areas.'},
{id:244,topic:'core-testing',difficulty:'advanced',question:'Which testing approach is described as "testing that the software can be tested"?',options:['Exploratory testing','Testability testing / testability analysis','Smoke testing','Configuration testing'],answer:1,explanation:'Testability analysis evaluates whether the system\'s design and implementation have the properties (observability, controllability, decomposability) that enable effective testing.'},
{id:245,topic:'core-testing',difficulty:'advanced',question:'In the context of software quality, what does ISO 25010 (SQuaRE) replace?',options:['IEEE 829','ISO 9126','IEEE 1012','CMMI'],answer:1,explanation:'ISO/IEC 25010 (SQuaRE — Software Quality Requirements and Evaluation) replaced ISO/IEC 9126, adding new quality characteristics (security, compatibility) and updating sub-characteristics.'},
{id:246,topic:'core-testing',difficulty:'advanced',question:'What is "metamorphic testing"?',options:['Testing shape-shifting or dynamic UI elements','A test oracle technique that defines metamorphic relations — expected patterns of output change when input is systematically transformed — to verify correctness without a definitive oracle','A technique for testing data transformation pipelines','Testing that APIs maintain backward compatibility'],answer:1,explanation:'Metamorphic testing addresses the oracle problem: rather than knowing the exact correct output, testers define how outputs should change when inputs are transformed (e.g., adding a constant to inputs should proportionally change outputs).'},
{id:247,topic:'core-testing',difficulty:'advanced',question:'What is "combinatorial test design" and when is it most valuable?',options:['Designing tests by combining all available test tools','Systematically testing combinations of parameter values (all-pairs, N-way) to detect interaction-based faults efficiently','Writing test cases in combination with developers','Testing systems that combine multiple programming languages'],answer:1,explanation:'Combinatorial test design (pairwise/N-way) is most valuable for systems with many configuration parameters or interacting inputs where exhaustive testing is impractical.'},
{id:248,topic:'core-testing',difficulty:'advanced',question:'What quality attribute does "observability" support in a testable system?',options:['Performance efficiency','Testability — the ability to determine outputs and internal state needed to verify test outcomes','Security — monitoring threats through logging','Usability — visible system status to users'],answer:1,explanation:'Observability means the system exposes sufficient state, output, and logging to allow testers to determine whether behaviour is correct — a critical property for testability.'},
{id:249,topic:'core-testing',difficulty:'advanced',question:'In "testing in production" (TiP), which technique gradually rolls out a new feature to a small percentage of users first?',options:['Canary deployment','Blue-green deployment','A/B testing','Shadow mode testing'],answer:0,explanation:'Canary deployment rolls out a change to a small subset of users first to monitor for errors before expanding to the full user base, limiting blast radius.'},
{id:250,topic:'core-testing',difficulty:'advanced',question:'What is the primary purpose of "synthetic monitoring" in production?',options:['Generating synthetic test data','Continuously running scripted user journeys against production systems to proactively detect availability and performance issues before real users are affected','Monitoring the performance of synthetic test environments','Recording all user interactions for privacy auditing'],answer:1,explanation:'Synthetic monitoring uses scripted simulated transactions executed on schedule against production to monitor uptime, response time, and functionality proactively.'},
{id:251,topic:'core-testing',difficulty:'beginner',question:'What is a "test stub" used for?',options:['Storing test cases','Simulating a component that the component under test calls, returning predetermined responses','Running the test suite in a CI pipeline','A partial implementation of a test script'],answer:1,explanation:'A stub replaces a called dependency with a minimal implementation that returns controlled responses, allowing the calling module to be tested in isolation.'},
{id:252,topic:'core-testing',difficulty:'beginner',question:'Which of the following correctly describes "functional testing"?',options:['Testing system performance under load','Verifying that the software performs its intended functions according to requirements','Testing the system\'s source code structure','Checking memory usage during execution'],answer:1,explanation:'Functional testing validates that the system\'s features and functions behave as specified in the requirements documentation.'},
{id:253,topic:'core-testing',difficulty:'beginner',question:'What does "test coverage" mean when applied to requirements?',options:['The number of test cases per requirement','The percentage of requirements that have at least one corresponding test case designed and/or executed','The complexity of the requirements','The total number of pages in the requirements document'],answer:1,explanation:'Requirements coverage measures what proportion of stated requirements are addressed by the test suite, ensuring no required functionality is left untested.'},
{id:254,topic:'core-testing',difficulty:'beginner',question:'Which of the following activities is part of "test planning"?',options:['Executing test cases','Logging defects','Defining the testing scope, objectives, approach, and schedule','Reviewing actual vs expected results'],answer:2,explanation:'Test planning defines the what, who, how, when, and how much of testing — scope, objectives, approach, resources, schedule, and exit criteria.'},
{id:255,topic:'core-testing',difficulty:'beginner',question:'What is "test implementation"?',options:['Executing test cases against the system','Creating the test data, test scripts, and test environment setup needed to run the planned test cases','Writing the test plan','Analysing test results'],answer:1,explanation:'Test implementation (test preparation) creates the concrete test scripts, test data, environment setup scripts, and automation code needed to execute the designed test cases.'},
{id:256,topic:'core-testing',difficulty:'beginner',question:'Which of the following is NOT a test level?',options:['Unit testing','Component integration testing','Regression testing','Acceptance testing'],answer:2,explanation:'Regression testing is a test type (verifying no regressions) not a test level. The four ISTQB test levels are: unit, integration, system, and acceptance testing.'},
{id:257,topic:'core-testing',difficulty:'beginner',question:'Which testing type evaluates how quickly a system responds to user interactions?',options:['Security testing','Performance testing','Compatibility testing','Acceptance testing'],answer:1,explanation:'Performance testing (specifically response time / response performance testing) measures how quickly the system responds to user actions under defined load conditions.'},
{id:258,topic:'core-testing',difficulty:'beginner',question:'What does "SDLC" stand for?',options:['Software Defect Lifecycle Cycle','Software Development Lifecycle','System Design and Layout Checklist','Software Deployment and Launch Control'],answer:1,explanation:'SDLC (Software Development Lifecycle) describes the structured process for planning, creating, testing, deploying, and maintaining software systems.'},
{id:259,topic:'core-testing',difficulty:'beginner',question:'What is the primary input for designing test cases?',options:['The test summary report from the previous release','The test basis (requirements, specifications, architecture, code, user stories)','The defect backlog from previous sprints','The test team\'s personal experience'],answer:1,explanation:'Test cases are designed from the test basis — all documented artefacts describing expected system behaviour such as requirements, use cases, and design specifications.'},
{id:260,topic:'core-testing',difficulty:'beginner',question:'A defect is logged against a feature, and the developer responds that the behaviour is actually correct per the specification. What status should the defect receive?',options:['Closed','Deferred','Rejected','In Progress'],answer:2,explanation:'If a defect is determined to be correct behaviour per specification, or a misunderstanding by the tester, it is typically marked "Rejected" (or "Not a Bug"), with a justification.'},
{id:261,topic:'core-testing',difficulty:'intermediate',question:'What is the key output of the "test analysis" activity?',options:['A list of passed and failed test cases','Identified test conditions derived from the test basis, along with their priority and coverage requirements','A completed test summary report','A list of automation test scripts'],answer:1,explanation:'Test analysis identifies what to test: it derives test conditions from the test basis (requirements, risks, acceptance criteria) and determines coverage targets.'},
{id:262,topic:'core-testing',difficulty:'intermediate',question:'Which technique uses a directed graph of nodes (states) and edges (transitions) to model expected behaviour and generate test cases?',options:['Decision tables','State transition testing','Cause-effect graphing','Equivalence partitioning'],answer:1,explanation:'State transition testing uses directed graphs (state diagrams) with nodes representing system states and edges representing event-triggered transitions, generating test sequences to cover states and transitions.'},
{id:263,topic:'core-testing',difficulty:'intermediate',question:'What is the purpose of "test case prioritisation" in regression testing?',options:['Ensuring the most recently written tests run first','Ordering test execution to maximise defect detection probability within available time, focusing first on high-risk or high-change areas','Running automated tests before manual tests','Prioritising tests by alphabetical order of the module name'],answer:1,explanation:'Prioritisation of regression tests ensures that if time runs out, the most critical tests (by risk, recent change impact, or failure history) have already been executed.'},
{id:264,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is a disadvantage of automated testing?',options:['Automated tests run slowly','High initial investment in setup, scripting, and maintenance; automation cannot replace exploratory thinking','Automated tests produce inconsistent results','Automation cannot test APIs'],answer:1,explanation:'Automation has high upfront costs (framework setup, scripting), ongoing maintenance overhead when the application changes, and cannot replicate exploratory, judgement-based testing.'},
{id:265,topic:'core-testing',difficulty:'intermediate',question:'What is "monkey testing"?',options:['Testing by developers only','Random or pseudo-random input testing, where random actions are performed without predefined scripts to find crashes and unexpected behaviours','Testing for memory leaks by repeatedly running the application','Testing the application on multiple device types'],answer:1,explanation:'Monkey testing (or fuzzing at the UI level) uses random inputs and interactions to find crashes and unexpected states; it is particularly useful for robustness testing.'},
{id:266,topic:'core-testing',difficulty:'intermediate',question:'In what way does "boundary value analysis" extend "equivalence partitioning"?',options:['BVA removes the need for EP by testing all boundaries','BVA tests the boundary values (min, max, and just inside/outside) of each equivalence partition, targeting the most common developer error locations','BVA and EP are completely different techniques with no relationship','BVA only applies to performance testing'],answer:1,explanation:'BVA complements EP: EP identifies the partitions; BVA then tests the edges of those partitions (±1 from boundaries) where off-by-one defects most commonly reside.'},
{id:267,topic:'core-testing',difficulty:'intermediate',question:'What is the concept of "test levels" designed to achieve?',options:['Ensure all tests are automated','Organise testing activities by scope and type (unit to acceptance), allowing defects to be detected at the most appropriate and cost-effective stage','Measure tester performance at different skill levels','Define the number of testing rounds required'],answer:1,explanation:'Test levels (unit, integration, system, acceptance) structure testing from small-scope/low-cost (unit) to large-scope/high-cost (acceptance), ensuring appropriate defect detection at each stage.'},
{id:268,topic:'core-testing',difficulty:'intermediate',question:'What is "test bed" in testing terminology?',options:['The physical location where testers work','The complete test environment including hardware, software, network, test data, and tools configured to support test execution','A subset of test cases that form a test suite','The test management dashboard'],answer:1,explanation:'A test bed is the complete configured environment — hardware, OS, network, test tools, application under test, and test data — set up specifically to support testing activities.'},
{id:269,topic:'core-testing',difficulty:'intermediate',question:'Which type of testing is concerned with how a system behaves when it is first installed, and how it is removed without affecting the rest of the system?',options:['Regression testing','Installation / uninstallation testing','Performance testing','Acceptance testing'],answer:1,explanation:'Installation testing verifies that the installation, upgrade, and uninstallation processes work correctly on all target platforms, leaving the system in the expected state.'},
{id:270,topic:'core-testing',difficulty:'intermediate',question:'What is the purpose of "usability heuristic evaluation"?',options:['Measuring response times for UI interactions','Experts evaluate the UI against established usability principles (Nielsen\'s heuristics) to identify usability problems without user participants','Automated scanning of UI code for errors','Load testing of user interface performance'],answer:1,explanation:'Heuristic evaluation has experts check the UI against usability principles (visibility, feedback, error prevention, consistency, etc.) to identify potential usability issues efficiently and cheaply.'},
{id:271,topic:'core-testing',difficulty:'advanced',question:'What does "test architecture" define in a large enterprise testing programme?',options:['The physical layout of test machines in the server room','The overall structure of the test automation and testing infrastructure: frameworks, tool selections, integration patterns, environments, and data strategies supporting the entire organisation','The architecture of the application under test','The reporting hierarchy for the test team'],answer:1,explanation:'Test architecture defines the enterprise-wide testing infrastructure: tool standards, automation frameworks, environment topology, test data strategies, and integration with CI/CD — enabling consistent, scalable testing across teams.'},
{id:272,topic:'core-testing',difficulty:'advanced',question:'What is "resilience testing" (also called reliability testing)?',options:['Testing that test scripts are resilient to UI changes','Subjecting the system to degraded conditions (hardware failures, partial network outages, resource exhaustion) to verify it degrades gracefully and recovers correctly','Testing the resilience of the development team during crunch time','Load testing at maximum concurrency'],answer:1,explanation:'Resilience testing verifies the system\'s ability to maintain acceptable function under adverse conditions and recover automatically — key for high-availability systems.'},
{id:273,topic:'core-testing',difficulty:'advanced',question:'In software testing, what is a "test oracle problem"?',options:['Finding a test management tool that acts as an oracle','The challenge of determining what the correct expected output should be, especially for complex systems where no definitive reference exists','A problem with Oracle Database test connections','Deciding which test tools to use'],answer:1,explanation:'The oracle problem occurs when testers cannot objectively determine the correct expected output — common in AI/ML systems, complex calculations, or legacy systems without documentation.'},
{id:274,topic:'core-testing',difficulty:'advanced',question:'What is "fuzz testing" (fuzzing)?',options:['Testing with blurry or unclear requirements','A technique that sends large amounts of random, malformed, or unexpected input data to a program to discover security vulnerabilities, crashes, and memory issues','Testing the application\'s fuzzy search functionality','Performance testing with variable user loads'],answer:1,explanation:'Fuzzing automatically generates malformed or random input to discover buffer overflows, injection vulnerabilities, crashes, and memory corruption — widely used in security testing.'},
{id:275,topic:'core-testing',difficulty:'advanced',question:'What is "penetration testing" and how does it differ from vulnerability scanning?',options:['They are identical','Penetration testing actively attempts to exploit identified vulnerabilities, simulating real attacks; vulnerability scanning only identifies and catalogues potential vulnerabilities without exploitation','Penetration testing is automated; vulnerability scanning is manual','Vulnerability scanning covers the entire system; penetration testing only covers the network'],answer:1,explanation:'Pen testing actively exploits vulnerabilities to determine actual impact and reach (ethical hacking). Vulnerability scanning passively identifies potential weaknesses without exploiting them.'},
{id:276,topic:'core-testing',difficulty:'advanced',question:'What is "coverage-directed test generation" (CDG)?',options:['Generating test cases from a code coverage report by identifying uncovered paths and creating inputs that exercise them','Generating coverage reports from existing tests','A manual technique for improving branch coverage','Using AI to generate test cases from images of the UI'],answer:0,explanation:'CDG analyses which code paths are uncovered by existing tests, then automatically generates new test inputs specifically designed to exercise those paths, improving structural coverage.'},
{id:277,topic:'core-testing',difficulty:'advanced',question:'Which ISO standard specifically addresses software testing processes?',options:['ISO 9001','ISO/IEC/IEEE 29119','ISO 25010','ISO 27001'],answer:1,explanation:'ISO/IEC/IEEE 29119 is the international standard specifically for software testing — covering concepts, processes, documentation, techniques, and keyword-driven testing.'},
{id:278,topic:'core-testing',difficulty:'advanced',question:'What is the difference between "verification" and "testing" in the context of formal methods?',options:['There is no difference','Verification in formal methods uses mathematical proof to demonstrate correctness; testing uses execution of the program to detect failures','Verification is done by QA; testing is done by developers','Testing is formal; verification is informal'],answer:1,explanation:'Formal verification uses mathematical proofs (model checking, theorem proving) to demonstrate properties hold for all inputs. Testing samples a finite subset of inputs to find failures — it cannot prove correctness.'},
{id:279,topic:'core-testing',difficulty:'advanced',question:'What is "test debt" accumulation most commonly caused by in agile projects?',options:['Having too many automated tests','Repeatedly sacrificing test quality (skipping testing, not automating regressions) to meet sprint velocity targets','Using the wrong test management tool','Hiring inexperienced testers'],answer:1,explanation:'Test debt accumulates when teams consistently deprioritise testing quality — skipping automation, not reviewing tests, accepting known gaps — often under schedule pressure that is never adequately addressed in future sprints.'},
{id:280,topic:'core-testing',difficulty:'advanced',question:'In a DevOps pipeline, what is the role of "shift-right" testing techniques like canary analysis?',options:['Moving QA staff to later stages of the SDLC','Using automated comparison of metrics between old and new deployment versions to detect quality regressions before full rollout','Delaying all testing until after deployment','Testing the product at the end of the development lifecycle'],answer:1,explanation:'Canary analysis compares performance, error rates, and business metrics between the canary (new) and baseline (old) deployment, automatically promoting or rolling back based on observed quality signals.'},
{id:281,topic:'core-testing',difficulty:'beginner',question:'What is "test execution" in the context of automated testing?',options:['Writing automated test scripts','Running automated test scripts against the application and collecting results','Designing the test framework architecture','Reviewing test results with stakeholders'],answer:1,explanation:'Automated test execution runs pre-written scripts against the application under test, comparing actual to expected outputs and reporting results — typically triggered by CI pipelines.'},
{id:282,topic:'core-testing',difficulty:'beginner',question:'Which of the following is a sign that a defect report is poorly written?',options:['It includes a screenshot','The actual result clearly differs from the expected result','The steps to reproduce are "it doesn\'t work" with no specific details','It references the specific build number'],answer:2,explanation:'Vague steps like "it doesn\'t work" are a classic sign of a poor defect report; testers must provide specific, repeatable steps that any developer can follow to reproduce the issue.'},
{id:283,topic:'core-testing',difficulty:'beginner',question:'What does "blocked" status mean for a test case?',options:['The test case has been completed successfully','The test case cannot be executed due to an unresolved prerequisite, dependency, or defect blocking further progress','The test case is awaiting assignment','The test case was executed but the result was inconclusive'],answer:1,explanation:'A blocked test case cannot be executed because a dependency is unavailable (e.g., a prerequisite feature is broken, environment is down, or a blocking defect exists).'},
{id:284,topic:'core-testing',difficulty:'beginner',question:'What is the main benefit of using test management tools?',options:['They automatically write test cases','They provide centralised storage, tracking, and reporting for test cases, execution results, defects, and coverage — improving team collaboration and visibility','They replace the need for a test plan','They automatically fix defects'],answer:1,explanation:'Test management tools (Jira, TestRail, Zephyr, qTest) centralise all testing artefacts and metrics, enabling teams to track coverage, execution status, and quality trends efficiently.'},
{id:285,topic:'core-testing',difficulty:'beginner',question:'What does "test automation framework" provide?',options:['A physical server for running tests','A reusable structure of tools, libraries, standards, and conventions that guides how automated tests are built, organised, and executed','A complete set of pre-written test cases for all applications','A user interface for manual test execution'],answer:1,explanation:'A test automation framework provides the scaffolding — libraries, utilities, reporting, configuration, and conventions — upon which automated tests are built, reducing duplication and improving maintainability.'},
{id:286,topic:'core-testing',difficulty:'beginner',question:'What is "software quality"?',options:['The absence of all defects in the software','The degree to which the software meets its stated and implied requirements, user expectations, and quality characteristics','The speed at which the software can be delivered','The number of test cases written for the software'],answer:1,explanation:'Software quality is the overall degree to which a software product meets its specified requirements, user needs, and quality standards (ISO 25010) — encompassing both functional and non-functional attributes.'},
{id:287,topic:'core-testing',difficulty:'beginner',question:'Which of the following is an example of a "test type"?',options:['Unit testing','Smoke testing','Regression testing','All of the above'],answer:3,explanation:'Test types categorise testing by objective or technique: functional, non-functional, structural, change-related. Unit, smoke, and regression testing are all types of testing.'},
{id:288,topic:'core-testing',difficulty:'beginner',question:'What is the role of a "test analyst"?',options:['Writing the deployment scripts','Analysing the test basis, identifying test conditions, designing and reviewing test cases, and contributing to test reporting','Managing the development team','Performing only automated testing'],answer:1,explanation:'A test analyst analyses requirements to identify testable conditions, designs test cases, contributes to test design documentation, and provides analysis during test execution and reporting.'},
{id:289,topic:'core-testing',difficulty:'beginner',question:'What is "test monitoring" in project management?',options:['Installing software monitoring agents on test servers','Continuously tracking test progress against the plan, collecting metrics, and reporting deviations to stakeholders so corrective action can be taken','Monitoring competitor test practices','Recording test execution screen captures'],answer:1,explanation:'Test monitoring tracks planned vs actual execution progress, pass/fail rates, defect trends, and coverage, enabling test managers to identify issues early and adjust the plan.'},
{id:290,topic:'core-testing',difficulty:'beginner',question:'Which of the following is a typical "exit criterion" for unit testing?',options:['All requirements have been reviewed','80% or higher statement coverage with all unit tests passing','The system is deployed to staging','Acceptance tests have been executed'],answer:1,explanation:'A typical unit testing exit criterion requires a minimum statement/branch coverage threshold (e.g., 80%) and all written unit tests passing with no critical failures.'},
{id:291,topic:'core-testing',difficulty:'intermediate',question:'What does "ISTQB Agile Tester Extension" focus on?',options:['Advanced automation frameworks for agile teams','Testing practices, principles, and techniques specifically for agile software development methods including Scrum and Kanban','Project management for agile QA teams','Certification for DevOps engineers'],answer:1,explanation:'The ISTQB Agile Extension covers testing in agile contexts: agile testing principles, practices, test automation in sprints, Scrum/Kanban-specific testing activities.'},
{id:292,topic:'core-testing',difficulty:'intermediate',question:'Which of the following best describes "testing in context" as defined by ISTQB?',options:['Testing software in the context of the user interface','Adapting the testing approach, techniques, and level of formality to the project type, risks, constraints, and domain','Testing only in the development environment','Using context-sensitive localisation for test data'],answer:1,explanation:'"Testing is context-dependent" means the correct testing approach varies by domain (safety-critical vs e-commerce), methodology (agile vs waterfall), risk level, and regulatory requirements.'},
{id:293,topic:'core-testing',difficulty:'intermediate',question:'What is the relationship between "test basis" and "test coverage"?',options:['Test coverage measures how well test execution results were recorded','Test coverage measures the extent to which test cases derived from the test basis have been executed against the coverage items (requirements, code paths, etc.)','Test basis defines the test coverage targets; test coverage measures execution completeness against those targets','They are unrelated concepts'],answer:2,explanation:'The test basis provides the items to be covered (requirements, decision branches, states); test coverage measures how many of those items have been exercised by the executed test cases.'},
{id:294,topic:'core-testing',difficulty:'intermediate',question:'In a testing lifecycle, "test completion" means:',options:['All test cases have passed','Testing activities for the phase/project are complete: remaining artefacts archived, test summary report issued, and lessons learned captured','The test plan has been approved','All defects have been resolved'],answer:1,explanation:'Test completion (closure) occurs when exit criteria are met: remaining issues documented, artefacts archived, test summary report delivered, and lessons learned recorded for process improvement.'},
{id:295,topic:'core-testing',difficulty:'intermediate',question:'What is "test environment management" responsible for?',options:['Writing test cases','Provisioning, maintaining, and retiring test environments to ensure they are available, stable, and correctly configured for test execution','Managing the test team budget','Deploying application builds to production'],answer:1,explanation:'Test environment management ensures that test environments are provisioned correctly, kept in sync with production configurations, maintained stably, and made available on schedule.'},
{id:296,topic:'core-testing',difficulty:'intermediate',question:'In performance testing, what does "throughput" measure?',options:['The number of test cases executed per minute','The number of transactions or requests the system can process per unit of time','The time taken for a single transaction to complete','The CPU usage during peak load'],answer:1,explanation:'Throughput measures system capacity: transactions per second (TPS), requests per second (RPS), or messages per second — indicating the volume the system can handle.'},
{id:297,topic:'core-testing',difficulty:'intermediate',question:'What is "regression risk" in the context of test planning?',options:['Risk that regression tests will fail due to environment instability','The probability that a code change in one area introduces unintended defects in previously working areas of the system','Risk of running too many regression tests','The risk of skipping regression testing altogether'],answer:1,explanation:'Regression risk is the probability that changes (new features, bug fixes, refactoring) unintentionally break existing functionality; it is managed through comprehensive regression suites.'},
{id:298,topic:'core-testing',difficulty:'intermediate',question:'What does the term "FIRST" stand for in the context of unit test principles?',options:['Functional, Integrated, Reliable, Stable, Thorough','Fast, Isolated/Independent, Repeatable, Self-validating, Timely','Full, Independent, Robust, Structured, Trustworthy','Functional, Independent, Regression-safe, Scalable, Testable'],answer:1,explanation:'FIRST principles for unit tests: Fast (run quickly), Isolated/Independent (no shared state), Repeatable (same result every time), Self-validating (pass or fail without manual inspection), Timely (written close to the code they test).'},
{id:299,topic:'core-testing',difficulty:'intermediate',question:'What is the "test case lifecycle"?',options:['The sequence of events from system requirements to software release','The progression of a test case from creation and review, through approval, execution, and ultimately archiving or retirement','The process of creating automated test scripts','The stages of a defect from new to closed'],answer:1,explanation:'A test case lifecycle tracks the test case from: design → peer review → approval → execution → result recording → maintenance/update → retirement when the feature is removed.'},
{id:300,topic:'core-testing',difficulty:'intermediate',question:'Which of the following describes "negative path testing" for an API?',options:['Testing the API with extremely low latency connections','Sending invalid request formats, missing required fields, wrong data types, or unauthorised requests to verify the API returns correct error codes and messages','Testing the API during off-peak hours','Testing all API endpoints in reverse order'],answer:1,explanation:'Negative API testing verifies error handling: invalid inputs, missing fields, unauthorised access, malformed JSON — ensuring the API returns appropriate error codes (400, 401, 422) and meaningful error messages.'},
{id:301,topic:'core-testing',difficulty:'advanced',question:'What is "risk-based testing" fundamentally different from "requirements-based testing"?',options:['Risk-based testing does not use requirements','Risk-based testing prioritises test effort according to business/technical risk, not just to achieve 100% requirements coverage','Requirements-based testing always finds more defects','They cannot be used together'],answer:1,explanation:'Requirements-based testing aims to cover all requirements equally; risk-based testing allocates proportionally more test effort to requirements whose failure would cause greatest business harm.'},
{id:302,topic:'core-testing',difficulty:'advanced',question:'What is "keyword-driven testing" in test automation?',options:['Searching for keywords in requirements documents','A test automation approach where tests are described using keywords (actions like "click", "verify", "input") that are mapped to implementation code, separating test design from automation code','Testing the application\'s search keyword functionality','A method for tagging test cases with metadata keywords'],answer:1,explanation:'Keyword-driven testing separates test design (keyword tables created by anyone) from automation implementation (keywords mapped to code by engineers), enabling non-technical users to define tests.'},
{id:303,topic:'core-testing',difficulty:'advanced',question:'What is "data-driven testing" (DDT)?',options:['Testing data-intensive applications like data warehouses','An automation pattern where the same test logic is executed multiple times with different sets of input data and expected results stored in external files (CSV, Excel, database)','Testing the data layer of an application','Driving test prioritisation decisions from data analytics'],answer:1,explanation:'Data-driven testing parameterises test scripts: test data (inputs and expected results) is externalised to files/databases, and the same test logic runs with each data row — maximising coverage without duplicating scripts.'},
{id:304,topic:'core-testing',difficulty:'advanced',question:'In continuous integration, what is a "broken build"?',options:['A compilation error in the test framework','A CI pipeline run where code compilation, unit tests, or quality gates fail, indicating the commit broke something and blocking further pipeline progression','A performance regression in the CI server','An incomplete commit pushed without tests'],answer:1,explanation:'A broken build occurs when the CI pipeline fails (compilation error, unit test failure, quality gate violation); the team is expected to stop and fix it immediately to restore pipeline health.'},
{id:305,topic:'core-testing',difficulty:'advanced',question:'What is "zero-day vulnerability" testing in security testing?',options:['Testing on the first day of a sprint','Identifying and testing for vulnerabilities that are not yet publicly known or patched — requiring proactive threat modelling and penetration testing','Testing with zero production data','Performance testing with zero concurrency'],answer:1,explanation:'Zero-day vulnerabilities are undisclosed, unpatched flaws; security testers use threat modelling, fuzzing, and penetration testing to proactively identify such vulnerabilities before attackers exploit them.'},
{id:306,topic:'core-testing',difficulty:'advanced',question:'What does "OWASP Top 10" represent in security testing?',options:['The 10 most popular web frameworks to test','The 10 most critical web application security risks, published by OWASP to guide security testing priorities','A 10-step penetration testing methodology','The 10 most common performance issues in web applications'],answer:1,explanation:'OWASP Top 10 catalogues the most critical and prevalent web application security risks (injection, XSS, broken authentication, etc.) and guides security testing priorities and countermeasures.'},
{id:307,topic:'core-testing',difficulty:'advanced',question:'In test automation, what is "test recording and playback"?',options:['Recording and replaying performance test sessions','An automation technique where user interactions are captured and saved as scripts that can be replayed — fast to create but brittle and high-maintenance for complex applications','Recording defects on video for developers to review','A method for documenting exploratory test sessions'],answer:1,explanation:'Record-and-playback generates automation scripts by capturing user actions; while quick to create, scripts are brittle (break with any UI change) and harder to maintain than code-written tests.'},
{id:308,topic:'core-testing',difficulty:'advanced',question:'What is "self-healing test automation"?',options:['Test cases that automatically fix application defects','AI/ML-powered automation that detects when UI element locators break due to application changes and automatically updates them, reducing maintenance effort','Tests that retry themselves on failure','Automated test report generation'],answer:1,explanation:'Self-healing automation uses AI to detect when a locator (selector) fails to find an element and intelligently selects an alternative locator, reducing test maintenance when the UI changes.'},
{id:309,topic:'core-testing',difficulty:'advanced',question:'In the context of CI/CD, what is "blue-green deployment testing"?',options:['Testing applications with blue and green color themes','Running two identical production environments (blue and green); the new version is deployed to the idle environment and tested before traffic is switched over, enabling instant rollback','Testing the network infrastructure color-coded routing rules','A testing strategy for dual-branch git workflows'],answer:1,explanation:'Blue-green deployment maintains two production-identical environments; the new release is fully tested in the inactive environment before traffic is switched, with instant rollback by reverting traffic.'},
{id:310,topic:'core-testing',difficulty:'advanced',question:'What is "A/B testing" in the context of software quality?',options:['Testing two different versions of the same test case','Running two variants of a feature simultaneously with different user segments to measure which performs better on defined business metrics','Testing applications in two different environments','Comparing automated and manual test results'],answer:1,explanation:'A/B testing (split testing) exposes different user cohorts to variant A and B of a feature, measuring metrics (conversion, engagement, error rate) to make data-driven product decisions.'},
{id:311,topic:'core-testing',difficulty:'beginner',question:'What does "severity" determine in defect classification?',options:['How soon the defect should be fixed','The level of impact the defect has on the system\'s functionality','Who should fix the defect','The cost to fix the defect'],answer:1,explanation:'Severity describes the degree of impact the defect has on system operation (critical → application crashes, major → feature unusable, minor → cosmetic).'},
{id:312,topic:'core-testing',difficulty:'beginner',question:'What is a "test suite" used for?',options:['To store test management tool configuration','To group related test cases for execution as a unit, often representing a feature or sprint scope','To record defects found during testing','To define testing roles and responsibilities'],answer:1,explanation:'A test suite is a collection of test cases grouped logically — typically by feature, module, or risk level — and executed together as a unit during test cycles.'},
{id:313,topic:'core-testing',difficulty:'beginner',question:'Which of the following is NOT a test type defined by ISTQB?',options:['Functional testing','Non-functional testing','Database testing','Structural (white-box) testing'],answer:2,explanation:'ISTQB defines four main test types: functional, non-functional, structural (white-box), and change-related (regression). "Database testing" is not a recognised ISTQB test type category.'},
{id:314,topic:'core-testing',difficulty:'beginner',question:'What does "actual result" mean in a test case?',options:['The input data used in the test','What the system actually produced or did when the test case was executed','The expected correct behaviour','The severity of the defect found'],answer:1,explanation:'The actual result is what the system under test actually produced during execution; it is compared against the expected result to determine pass or fail.'},
{id:315,topic:'core-testing',difficulty:'beginner',question:'Which of the following describes "test completion criteria"?',options:['The conditions that define when a new test cycle begins','The measurable conditions that, when met, indicate sufficient testing has been completed for a phase or iteration','The budget allocated for testing activities','The technology stack used for automation'],answer:1,explanation:'Test completion criteria define the objective conditions — pass rate, coverage threshold, defect count — that signal a test phase can be formally closed and a release decision made.'}
]);
